-- ----------------------------------------------------------------------------
-- Customers: Table: Customers
-- ----------------------------------------------------------------------------
CREATE TABLE customers (
  customer_id                         TEXT                 PRIMARY KEY,
  name                                TEXT                ,                     -- Human-readable customer name.
  notes                               TEXT                ,                     -- Free-form notes about the customer.
  status                              TEXT                ,                     -- Link to the customer's current Status in the Statuses table.
  email                               TEXT                ,                     -- Primary email address for the customer.
  phone                               TEXT                ,                     -- Primary phone number for the customer.
  company_name                        TEXT                ,                     -- Company the customer represents, if applicable.
  billing_address                     TEXT                ,                     -- Default billing address for the customer.
  shipping_address                    TEXT                ,                     -- Default shipping address for the customer.
  created_at                          TIMESTAMPTZ                               -- Timestamp when the customer record was created.
);
COMMENT ON TABLE customers IS 'Table: Customers';
COMMENT ON COLUMN customers.name IS 'Human-readable customer name.';
COMMENT ON COLUMN customers.notes IS 'Free-form notes about the customer.';
COMMENT ON COLUMN customers.status IS 'Link to the customer''s current Status in the Statuses table.';
COMMENT ON COLUMN customers.email IS 'Primary email address for the customer.';
