COMMENT ON COLUMN customers.company_name IS 'Company the customer represents, if applicable.';
COMMENT ON COLUMN customers.billing_address IS 'Default billing address for the customer.';
COMMENT ON COLUMN customers.shipping_address IS 'Default shipping address for the customer.';
