  quantity                            INTEGER             ,                     -- Number of units ordered on this line.
  unit_price                          NUMERIC             ,                     -- Price per unit captured at the time of ordering (may differ from current Product.UnitPrice).
  discount_percent                    NUMERIC             ,                     -- Per-line discount applied to this item.
  notes                               TEXT                                      -- Free-form notes about this line item.
);
COMMENT ON TABLE order_line_items IS 'Table: OrderLineItems';
COMMENT ON COLUMN order_line_items.line_number IS 'Position of this line within its parent Order (e.g. ''1'', ''2''). Combined with Order to form the line item''s natural key.';
